// GOLD-001 — the workspace this kit has actually produced, scored against the real scorers.
// Requirement: ai-evals.md · REQ-NF-007 · BR-002 · ADR-003 · ADR-006.
//
// Every other test in this suite checks the kit's PARTS. This one checks its OUTPUT: a
// workspace generated by following instructions/intake.md against a clean repository, at
// express depth, using EV-001's answers.
//
// It exists because whole classes of defect were invisible to part-tests and surfaced within
// minutes of a real run:
//
//   BUG-008  24 blueprints carried a worked example ADR-003 step 2 could not strip, so
//            "TeamTask Lite" and "SaaS task app" would have shipped as the developer's own
//            decisions. The C2 test skipped exactly those files.
//   BUG-010  Round 1 had to write its acceptance row into a file Round 8 owned.
//   BUG-012  express capped a round at two questions and gave a rule that selected four.
//   BUG-013  check 6 went silent the moment one Q-### existed — which Round 2 creates.
//   BUG-014  a later round's answer had no way to reach an earlier round's [TODO].
//   BUG-015  the change-log blueprint cited the KIT's ADR numbers in text that ships, so
//            every generated workspace failed check 1 on identifiers it never defined.
//
// A synthetic workspace built inside a test would have had none of them, because the author
// of the test also authors the input. This fixture was not authored — it was produced.
//
// ONE FIXTURE, GROWN ROUND BY ROUND. Not a snapshot per round: Round 1's four files would
// then exist in eight places and drift apart at the first correction, which is the
// duplication this design refuses everywhere else. How far the run has got is read from the
// acceptance rows in the change log — the artifact already records it, so nothing needs a
// state file to say so (ADR-004, ADR-006).

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync, readdirSync, statSync } from 'node:fs'
import { join } from 'node:path'
import { score } from '../../ci/eval-runner.mjs'
import { acceptedStages, forbiddenStateFiles } from '../../ci/acceptance.mjs'
import { validate } from '../../ci/validation.mjs'
import { unfilled, todos, blueprintOf } from '../../ci/fill.mjs'

const ROOT = 'tests/fixtures/golden/EV-001'

const walk = (d, acc = []) => {
  for (const e of readdirSync(d)) {
    const p = join(d, e)
    statSync(p).isDirectory() ? walk(p, acc) : acc.push(p)
  }
  return acc
}

const workspace = Object.fromEntries(
  walk(ROOT).map((p) => [p.slice(ROOT.length + 1).split('\\').join('/'), readFileSync(p, 'utf8')])
)

const library = readFileSync('plugin/blueprints/MANIFEST.md', 'utf8')
  .split('\n')
  .map((l) => (l.match(/^\| `([^`]+)` \|/) || [])[1])
  .filter(Boolean)

const changeLog = workspace['spec/01-docs/09-change-control/spec-change-log.md']

/** How far the run has got, read from the artifact rather than from a filename. */
const rounds = acceptedStages(changeLog).length
const scored = score({ workspace, library, rounds, outside: [] })
const failing = scored.breaches.map((b) => b.name).sort()

// --- What has been produced -------------------------------------------------------------------

test('GOLD-001: the run has reached Round 2, and the artifact is what says so', () => {
  assert.deepEqual(acceptedStages(changeLog), ['Round 1 — the idea', 'Round 2 — scope boundaries'])
  assert.equal(rounds, 2)
})

test('GOLD-001: every file belongs to a round that has actually run', () => {
  // Round 1 owns 01-docs/01-intent/ (intent, brief), 01-docs/09-change-control/, and the
  // workspace README. Round 2 owns the rest of 01-docs/01-intent/. Nothing from Round 3
  // onwards may appear — a file written ahead of its round is coverage the run has not
  // reached, which check 13 would then read as progress (coverage.md).
  assert.deepEqual(Object.keys(workspace).sort(), [
    'spec/01-docs/01-intent/constraints-and-non-goals.md',
    'spec/01-docs/01-intent/intent.md',
    'spec/01-docs/01-intent/open-questions.md',
    'spec/01-docs/01-intent/project-brief.md',
    'spec/01-docs/01-intent/subdomain-map.md',
    'spec/01-docs/09-change-control/spec-change-log.md',
    'spec/README.md',
  ])
})

test('GOLD-001: the workspace README is about THIS project, not about the template', () => {
  const readme = workspace['spec/README.md']
  assert.match(readme, /^# Pantry — specification workspace/m, 'it is named for the product')
  assert.doesNotMatch(readme, /\[project name\]/, 'and the field was actually filled')
  assert.doesNotMatch(readme, /Copy this folder for each new project/)
  assert.doesNotMatch(readme, /Gem Iroko/)
  assert.match(readme, /Not every file below exists yet/)
})

// --- BR-002: the failure that made BUG-008 worth finding --------------------------------------

test('GOLD-001: no example product reached the workspace', () => {
  const all = Object.values(workspace).join('\n')
  for (const name of ['ProjectBoard', 'TeamTask Lite', 'SaaS task app', 'WORKED EXAMPLE']) {
    assert.doesNotMatch(all, new RegExp(name), `${name} must not survive the fill`)
  }
})

test('GOLD-001: no identifier from the KIT survives into the workspace', () => {
  // BUG-015. The change-log blueprint cited ADR-004 and ADR-006 — this repository's own
  // decision records — in prose that ships. In the developer's repository those point at
  // nothing, and the day they write their own ADR-006 they point at the wrong thing. Check 1
  // reported it correctly, and would have done so on every workspace this kit ever made.
  const check1 = validate(workspace, library).results.find((c) => c.n === 1)
  assert.equal(check1.state, 'passed', check1.detail.join(' · '))
})

test('GOLD-001: every file carries a back-link that resolves to a real blueprint', () => {
  for (const [path, text] of Object.entries(workspace)) {
    const bp = blueprintOf(text)
    assert.ok(bp, `${path} has no back-link`)
    assert.ok(library.includes(bp), `${path} points at ${bp}, which is not in the library`)
  }
})

test('GOLD-001: no placeholder survived as body text', () => {
  for (const [path, text] of Object.entries(workspace)) {
    assert.deepEqual(unfilled(text), [], `${path} still holds an unfilled placeholder`)
  }
})

// --- ADR-006 / ADR-004: acceptance is a row, never a file -------------------------------------

test('GOLD-001: each round recorded its own acceptance as a dated row', () => {
  // BUG-010. Only possible because 01-docs/09-change-control/ moved to Round 1 — a file every
  // round writes to is created by the first round that writes to it.
  assert.equal(acceptedStages(changeLog).length, rounds)
})

test('GOLD-001: no state, progress or acceptance file exists anywhere', () => {
  assert.deepEqual(forbiddenStateFiles(Object.keys(workspace)), [])
})

// --- Round 2: what express asked, and what it refused to invent -------------------------------

test('GOLD-001: Round 2 asked its two express questions and recorded the other two', () => {
  const open = workspace['spec/01-docs/01-intent/open-questions.md']
  // Asked: capabilities (Q1) and the core subdomain (Q4). Q-001 closes as a result.
  assert.match(open, /\| Q-001 \| Which capabilities must exist in version one\? .*\| Answered \|/)
  // Not asked: out-of-scope (Q2) and constraints (Q3). Recorded, never answered for them.
  assert.match(open, /\| Q-002 \| Which capabilities are explicitly ruled out of version one\? .*\| Open \|/)
  assert.match(open, /\| Q-003 \| What hard constraints already exist.*\| Open \|/)
})

test('GOLD-001: the constraint table is MARKED, never filled with what usually applies', () => {
  // The most tempting defect in express depth. Every plausible default — no paid services,
  // one small server, no card data — would read exactly like a stated constraint, and a
  // constraint changes the architecture rather than decorating it (BUG-012).
  const con = workspace['spec/01-docs/01-intent/constraints-and-non-goals.md']
  const rows = con.match(/^\| CON-00\d \| [^|]+\| ([^|]+)\|/gm) ?? []
  assert.equal(rows.length, 8, 'all eight constraint types are present')
  for (const row of rows) {
    assert.match(row, /\[TODO:/, `a constraint nobody stated must not be written as one: ${row}`)
  }
  assert.match(con, /This table is marked, not filled, and that is deliberate/)
})

test('GOLD-001: unbuilt is distinguished from ruled out', () => {
  // Q-002 was not asked, so the workspace may claim what is IN scope and may not claim what
  // is out of it. Collapsing the two is how a capability nobody rejected becomes rejected.
  const con = workspace['spec/01-docs/01-intent/constraints-and-non-goals.md']
  assert.match(con, /Anything not on that list is unbuilt, not ruled out/)
})

test('GOLD-001: the subdomain map names one core, and leaves the blocked row blocked', () => {
  const map = workspace['spec/01-docs/01-intent/subdomain-map.md']
  const core = [...map.matchAll(/^\| ([^|]+)\| \*\*Core\*\* \|/gm)].map((m) => m[1].trim())
  assert.deepEqual(core, ['Turning a week of chosen meals into one shopping list'], 'exactly one core subdomain')

  // Generic says buy — unless a constraint forbids it, and then the row names the constraint
  // and stays undecided rather than defaulting to build (depth.md). CON-006 is unanswered
  // here, so this row is the visible price of the dropped question.
  assert.match(map, /Accounts and sign-in \| \*\*Generic\*\*/)
  assert.match(map, /Undecided — blocked on \[`CON-006`\]/)
})

// --- BUG-014: a marker whose question was answered ---------------------------------------------

test('GOLD-001: Round 2 closed the marker Round 1 left in files Round 2 does not own', () => {
  // The capability question was marked by Round 1 in intent.md and project-brief.md, and
  // answered by Round 2. Both markers are replaced; neither file was otherwise touched.
  for (const path of ['spec/01-docs/01-intent/intent.md', 'spec/01-docs/01-intent/project-brief.md']) {
    assert.doesNotMatch(workspace[path], /\[TODO: which capabilities must exist in version one\?\]/)
    assert.match(workspace[path], /Save a recipe with its ingredients/)
  }
  // And check 6 agrees: nothing is orphaned and nothing is stale.
  const check6 = validate(workspace, library).results.find((c) => c.n === 6)
  assert.equal(check6.state, 'passed', check6.detail.join(' · '))
})

// --- What is honestly still open --------------------------------------------------------------

test('GOLD-001: gaps are recorded as [TODO], not filled with plausible values', () => {
  const count = Object.values(workspace).reduce((n, t) => n + todos(t).length, 0)
  assert.ok(count > 0, 'a two-question interview cannot honestly fill an intent document')
  assert.ok(count < 60, 'but a workspace that is nothing but TODOs is not a specification')
})

test('GOLD-001: the ONE failing scorer is the unfinished run, not a defect', () => {
  // It was three at Round 1. Round 2 cleared todo_pairing — the [TODO]s now pair with Q-###
  // rows in open-questions.md — and ids_resolve, once BUG-015 removed the kit's own ADR
  // numbers from the shipped change log. What is left is check 13: 80 blueprints belong to
  // rounds 3 to 8 and the run has not reached them.
  //
  // Naming the list is the point. The day it changes, something real changed.
  assert.deepEqual(failing, ['structural_checks'])

  const v = validate(workspace, library)
  assert.deepEqual(v.results.filter((c) => c.state === 'failed').map((c) => c.n), [13])
  assert.match(v.results.find((c) => c.n === 13).detail[0], /blueprint\(s\) neither filled nor skipped/)
})

test('GOLD-001: an unreached blueprint is a coverage FAILURE, never a silent skip', () => {
  // coverage.md is explicit: not reaching a blueprint is the intake producing less than it
  // promised. Recording those 80 as "skipped" would turn an unfinished run into a finished
  // one on paper, which is the easiest way there is to fake this whole product.
  assert.doesNotMatch(changeLog, /\| Skipped \|/, 'nothing has been skipped in this run')
})

test('GOLD-001: BR-009 — a partial workspace may not claim success', () => {
  const v = validate(workspace, library)
  assert.equal(v.mayClaimSuccess, false)
  assert.ok(v.notRun > 0, 'and a check that could not run is not a check that passed')
})

test('GOLD-001: the scorers that must hold at ANY round do hold', () => {
  const ok = (name) => scored.results.find((x) => x.name === name).atFloor
  for (const name of ['no_leftover_template', 'no_example_content', 'boundary_respected', 'no_code_written', 'todo_pairing', 'ids_resolve']) {
    assert.equal(ok(name), true, `${name} must pass in a partial workspace too`)
  }
})

test('GOLD-001: todo_density is recorded, still ungated — one run of the ten Q-014 needs', () => {
  const density = scored.results.find((x) => x.name === 'todo_density')
  assert.equal(density.floor, null, 'Q-014 stays open until ten real runs exist')
  assert.ok(density.value > 0, 'and this run contributes a real number rather than a guess')
})
